// @pit: {"label": "Update docs and workflow for pit v0.39.2, pi 1.6.0, and the fit-images extension"}
async ({ workspace: { read, edit } }) => {
  const rep = async (file: string, pairs: [string, string][]) => {
    const f: any = await read(file, { format: "raw" });
    let c: string = f.content;
    for (const [a, b] of pairs) {
      if (!c.includes(a)) throw new Error(`${file}: missing ${a}`);
      c = c.split(a).join(b);
    }
    await edit(file, { revision: f.revision, changes: [{ kind: "replaceFile", content: c }] });
  };
  await rep("docs/extensions.md", [
    ["github:cv/pit#v0.39.0", "github:cv/pit#v0.39.2"],
    ["- pi-action installs the extensions after its coding tools (read, write, edit, bash). Each extension must have a unique name, other than `coding-tools` and `pi-action`.",
     "- pi-action installs the extensions after its coding tools (read, write, edit, bash). Each extension must have a unique name, other than `fit-images`, `coding-tools`, and `pi-action`."],
    ["The order is: the coding tools of pi-action (`coding-tools`) first, then its built-in extension `pi-action`, then the extensions in the order of the `extensions` input. Extensions cannot use the names `coding-tools` and `pi-action`.",
     "The order is: pi-durable's `fit-images` extension first, then the coding tools of pi-action (`coding-tools`), then its built-in extension `pi-action`, then the extensions in the order of the `extensions` input. Extensions cannot use the names `fit-images`, `coding-tools`, and `pi-action`."],
    ["| `images` | An image processor, `createNodePhotonImages()` of pi-durable. It resizes and converts images to the limits of the model, for example for pit's `workspace.viewImage` (pit 0.36.2 and later) |",
     "| `images` | An image processor, `createNodePhotonImages()` of pi-durable. It resizes and converts images to the limits of the model, for example for pit's `workspace.viewImage` (pit 0.36.2 and later). pi-action uses the same processor for `read` and for `fit-images` (see [Images](#images)) |"],
    ["pi-durable extensions run in the process of pi-action. Thus,",
     "### Images\n\npi-action fits each image that the model gets to the limits of the model, before the thread stores it. The image processor resizes and converts the images that `read` returns. The `fit-images` extension of pi-durable does the same for the results of all other tools, for example an MCP tool, and writes what it changed in an `info` diagnostic. Thus, a tool does not have to fit its images itself, and a large or damaged image does not stop the thread. The hooks of the extensions see the fitted images.\n\npi-durable extensions run in the process of pi-action. Thus,"],
  ]);
  await rep("docs/prompts.md", [["(pi 1.5.2, `buildSystemPromptSections`)", "(pi 1.6.0, `buildSystemPromptSections`)"]]);
  await rep(".github/workflows/pi-assistant.yml", [["github:cv/pit#v0.39.0", "github:cv/pit#v0.39.2"]]);
  return "ok";
}
